CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,username VARCHAR(50) NOT NULL,email VARCHAR(254) NOT NULL,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_users_username(username),UNIQUE KEY uq_users_email(email)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS dungeons(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,owner_user_id BIGINT UNSIGNED NULL,name VARCHAR(120) NOT NULL,seed VARCHAR(80) NOT NULL,width SMALLINT UNSIGNED NOT NULL,height SMALLINT UNSIGNED NOT NULL,level TINYINT UNSIGNED NOT NULL,theme VARCHAR(60) NOT NULL,map_json JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY ix_dungeons_created_at(created_at),KEY ix_dungeons_seed(seed),CONSTRAINT fk_dungeons_owner FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE SET NULL,CONSTRAINT chk_dungeons_width CHECK(width BETWEEN 21 AND 81),CONSTRAINT chk_dungeons_height CHECK(height BETWEEN 21 AND 61),CONSTRAINT chk_dungeons_level CHECK(level BETWEEN 1 AND 20)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS dungeon_rooms(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,dungeon_id BIGINT UNSIGNED NOT NULL,room_number SMALLINT UNSIGNED NOT NULL,x SMALLINT UNSIGNED NOT NULL,y SMALLINT UNSIGNED NOT NULL,width SMALLINT UNSIGNED NOT NULL,height SMALLINT UNSIGNED NOT NULL,room_type VARCHAR(32) NOT NULL DEFAULT 'chamber',metadata JSON NULL,PRIMARY KEY(id),UNIQUE KEY uq_dungeon_room_number(dungeon_id,room_number),CONSTRAINT fk_rooms_dungeon FOREIGN KEY(dungeon_id) REFERENCES dungeons(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS dungeon_encounters(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,dungeon_id BIGINT UNSIGNED NOT NULL,room_id BIGINT UNSIGNED NULL,encounter_type ENUM('monster','trap','treasure','puzzle','boss','event') NOT NULL,challenge_rating DECIMAL(5,2) NOT NULL DEFAULT 0,payload JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY ix_encounters_dungeon(dungeon_id),CONSTRAINT fk_encounters_dungeon FOREIGN KEY(dungeon_id) REFERENCES dungeons(id) ON DELETE CASCADE,CONSTRAINT fk_encounters_room FOREIGN KEY(room_id) REFERENCES dungeon_rooms(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS generation_presets(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,name VARCHAR(80) NOT NULL,description VARCHAR(500) NULL,options_json JSON NOT NULL,is_public BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY ix_presets_public(is_public,name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
